SELECT COUNT(*) FROM chat_session cs
WHERE cs.user_id = #{userId} AND cs.status = 1

    AND cs.session_title LIKE #{keyword}

mapper.sql:
SELECT cs.id, cs.session_title AS sessionTitle, cs.kb_id AS kbId, kb.kb_name AS kbName, cs.is_pinned AS isPinned, cs.created_at AS createdAt, cs.updated_at AS updatedAt FROM chat_session cs LEFT JOIN kb_knowledge_base kb ON kb.id = cs.kb_id WHERE cs.user_id = #{userId} AND cs.status = 1
AND cs.session_title LIKE #{keyword}
ORDER BY cs.is_pinned DESC, cs.updated_at DESC
